//! Text copied on the computer goes to the viewer in control, and a viewer's text comes onto the
//! computer's clipboard before it pastes there.

use objc2_app_kit::{NSPasteboard, NSPasteboardAccessBehavior, NSPasteboardTypeString};
use objc2_foundation::NSString;
use screen::link::MOST_CLIPBOARD;

/// Password managers mark what they copy so that clipboard tools leave it alone
/// (nspasteboard.org).
const PRIVATE: [&str; 3] = [
    "org.nspasteboard.ConcealedType",
    "org.nspasteboard.TransientType",
    "org.nspasteboard.AutoGeneratedType",
];

/// What the helper last saw on the clipboard or put there itself.
pub(super) struct Clipboard {
    seen: isize,
    /// The text that last went between the computer and a viewer, which a viewer's device or
    /// a shared clipboard such as Universal Clipboard brings back.
    last: Option<String>,
}

impl Clipboard {
    pub(super) fn new() -> Self {
        Self {
            seen: count(),
            last: None,
        }
    }

    /// True for text that did not just go between the computer and a viewer, which goes on.
    pub(super) fn is_new(&mut self, text: &str) -> bool {
        if self.last.as_deref() == Some(text) {
            return false;
        }
        self.last = Some(text.to_owned());
        true
    }

    /// Only what is copied from now on goes to viewers.
    pub(super) fn settle(&mut self) {
        self.seen = count();
    }

    /// True once something was copied since the helper last looked.
    pub(super) fn changed(&mut self) -> bool {
        let count = count();
        count != std::mem::replace(&mut self.seen, count)
    }

    pub(super) fn put(&mut self, text: &str) {
        self.last = Some(text.to_owned());
        let pasteboard = NSPasteboard::generalPasteboard();
        pasteboard.clearContents();
        // SAFETY: an AppKit constant.
        let kind = unsafe { NSPasteboardTypeString };
        pasteboard.setString_forType(&NSString::from_str(text), kind);
        self.seen = pasteboard.changeCount();
    }
}

fn count() -> isize {
    NSPasteboard::generalPasteboard().changeCount()
}

/// The copied text, unless it is private or too long, or the person at the computer does not
/// let Kodosi Screen read the clipboard. Reading may make macOS ask them first, so this runs
/// away from the link's thread.
pub(super) fn copied() -> Option<String> {
    let pasteboard = NSPasteboard::generalPasteboard();
    if pasteboard.accessBehavior() == NSPasteboardAccessBehavior::AlwaysDeny {
        return None;
    }
    let private = pasteboard.types()?.iter().any(|kind| {
        let kind = kind.to_string();
        PRIVATE.contains(&kind.as_str())
    });
    if private {
        return None;
    }
    // SAFETY: an AppKit constant.
    let kind = unsafe { NSPasteboardTypeString };
    let text = pasteboard.stringForType(kind)?.to_string();
    (!text.is_empty() && text.len() <= MOST_CLIPBOARD).then_some(text)
}
